-- =============================================================================================
-- SIPHO'S SEPTEMBER LIST -- the staff pivot, and the stock we have never locked.
-- =============================================================================================
--   "Use this excel to populate pivoted Staff table for existing RSM and Agents data, also for an
--    OLD STOCK new nav pane for all those stock that imei no does not exist in our new enrolled
--    phones."
--
-- Source: SEPTEMBER_UPDATED_LIST_FROM_SIPHO.xlsx -- 2682 handsets, 17 RSMs,
-- 222 agents. The ages in it were true on 2026-09-10, which is what `as_of` records: every
-- pane works out today's age as age_days + (today - as_of), so it keeps climbing on its own.
--
-- RUN db/migrations/RUN-ME-2026-09-12-old-stock.sql FIRST. This file fills the table that one
-- creates.
--
-- ---------------------------------------------------------------------------------------------
-- WHAT THIS WILL NOT DO, and it matters on a register that is already full.
-- ---------------------------------------------------------------------------------------------
-- Sipho's list knows a name, a phone and who somebody answers to. The register also holds a
-- branch, a national ID, next of kin, a joining date -- none of which are in this sheet. So every
-- column this file does not know is written with coalesce(): a blank here can never erase what is
-- already there. Filling a register from a narrower list is exactly how good data disappears.
--
-- NOBODY IS DEMOTED. Sixteen of the seventeen RSMs also carry stock of their own, so they appear
-- in both columns of the sheet. An RSM is written as Regional_Manager and a later row naming them
-- as an agent cannot turn them into a Field_Officer -- and an existing Country_Sales_Manager or
-- Team_Leader is left exactly as it is.
--
-- NOBODY IS SILENTLY REACTIVATED either. `active` is only set for rows this file CREATES; anybody
-- switched off on the staff pane stays off, because that switch now also shuts their login and
-- undoing it from a spreadsheet would be a door opening that nobody decided to open.
--
-- WHO IS MISSING, said out loud rather than invented. Five people in the sheet have no phone
-- number, and phone is this register's primary key -- there is nothing to file them under. They
-- are listed at the foot of this file. Their STOCK still loads (old_stock keeps the agent as
-- text, not as a link), so no handset is lost; only the staff row waits for a number.
--
-- Safe to run more than once.
-- =============================================================================================

-- ---------------------------------------------------------------------------------------------
-- 1. THE STAFF PIVOT: RSMs, then agents, then who answers to whom.
-- ---------------------------------------------------------------------------------------------
on conflict (phone) do update set
  name    = coalesce(nullif(excluded.name, ''), hoop_agents.name),
  /* THE LIST MAY PROMOTE, NEVER DEMOTE. An RSM who also carries stock appears twice in the
     sheet; the second appearance must not turn them into a field officer. And a rung this
     sheet does not know about -- Country_Sales_Manager, Team_Leader -- is left alone. */
  role    = case
              when hoop_agents.role is null or hoop_agents.role = '' then excluded.role
              when upper(replace(excluded.role, ' ', '_')) = 'REGIONAL_MANAGER'
               and upper(replace(hoop_agents.role, ' ', '_')) = 'FIELD_OFFICER' then excluded.role
              else hoop_agents.role
            end,
  /* WHO THEY ANSWER TO IS THE ONE THING THIS SHEET IS AUTHORITATIVE ABOUT -- it is the pivot
     the list was made from -- so a named RSM wins. A blank still never erases one. */
  manager = coalesce(nullif(excluded.manager, ''), hoop_agents.manager),
  updated_at = now();

-- The RSMs, as their own row, so a manager is always somebody the register knows.

-- ---------------------------------------------------------------------------------------------
-- 2. OLD STOCK: 2682 handsets we hold and have never locked.
--
-- All of them load, including any that happen to be enrolled already: a row leaves this list by
-- being FOUND in `devices` or in the sale book, which the panes ask at read time. Deciding it here
-- would freeze today's answer into the table and the two lists would drift apart by tomorrow.
-- ---------------------------------------------------------------------------------------------
on conflict (imei) do update set
  item        = coalesce(nullif(excluded.item, ''), old_stock.item),
  agent       = coalesce(nullif(excluded.agent, ''), old_stock.agent),
  agent_phone = coalesce(nullif(excluded.agent_phone, ''), old_stock.agent_phone),
  rsm         = coalesce(nullif(excluded.rsm, ''), old_stock.rsm),
  rsm_phone   = coalesce(nullif(excluded.rsm_phone, ''), old_stock.rsm_phone),
  /* A NEWER LIST RE-ZEROES THE AGE, an older one does not. Re-pasting September after October
     would otherwise wind every handset's age backwards by a month. */
  age_days    = case when excluded.as_of >= old_stock.as_of then excluded.age_days else old_stock.age_days end,
  as_of       = greatest(excluded.as_of, old_stock.as_of),
  source      = excluded.source,
  updated_at  = now();

-- ---------------------------------------------------------------------------------------------
